RUN_BODY = r'''
BEGIN
 IF OLD.status<>'RUNNING' THEN
  IF TG_OP='DELETE' OR (to_jsonb(OLD)-'parity_summary') IS DISTINCT FROM
      (to_jsonb(NEW)-'parity_summary') THEN
   RAISE EXCEPTION 'Terminal calculation identity is immutable'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END
'''

TRUNCATE_BODY = r'''
BEGIN
 RAISE EXCEPTION 'Accepted state owners cannot be truncated';
END
'''

COMMAND_BODY = r'''
DECLARE parent mta.fresh_mta_calculationrun; entry record; family text;
 physical text; binding text; actual bigint; metadata jsonb; operation text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Command history is retained'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state_sealed OR NEW.state_manifest<>'{}'::jsonb THEN
   RAISE EXCEPTION 'New commands require an unsealed append owner'; END IF;
 ELSE
  IF OLD.state_sealed OR NEW.state_sealed OR NEW.state_manifest='{}'::jsonb
    OR (to_jsonb(OLD)-'state_manifest') IS DISTINCT FROM (to_jsonb(NEW)-'state_manifest') THEN
   RAISE EXCEPTION 'Command identity is immutable; only its manifest can seal'; END IF;
 END IF;
 SELECT * INTO parent FROM mta.fresh_mta_calculationrun WHERE id=NEW.run_id FOR UPDATE;
 IF NOT FOUND OR parent.kind<>'DAILY_CHAIN' OR parent.status<>'SUCCEEDED'
   OR EXISTS(SELECT 1 FROM mta.fresh_mta_calculationrun
    WHERE predecessor_id=NEW.run_id AND status IN ('RUNNING','SUCCEEDED')) THEN
  RAISE EXCEPTION 'Command requires an eligible completed parent'; END IF;
 operation=NEW.payload->>'operation';
 IF operation IS NULL OR operation NOT IN ('APPLY','SLEEP','elephant_due_date') THEN
  RAISE EXCEPTION 'Unknown command state owner'; END IF;
 IF TG_OP='INSERT' THEN RETURN NEW; END IF;
 IF jsonb_typeof(NEW.state_manifest) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'Command manifest must be an object'; END IF;
 FOR entry IN SELECT key,value FROM jsonb_each(NEW.state_manifest) LOOP
  IF (operation='APPLY' AND entry.key<>'NormAcceptanceTbl')
    OR (operation='SLEEP' AND (entry.key NOT IN ('NormAcceptanceTbl','NormsInSleepModeTbl','Suggestions')
       OR (entry.key='NormAcceptanceTbl' AND jsonb_object_length_placeholder)))
    OR (operation='elephant_due_date' AND entry.key<>'ElephantOrders')
    OR entry.value->>'image' IS DISTINCT FROM ('action/'||NEW.id::text||'/'||entry.key)
    OR entry.value->>'table' IS DISTINCT FROM
       (CASE WHEN entry.key='ElephantOrders' THEN 'BPR/' ELSE 'DBM/' END||entry.key)
    OR COALESCE(entry.value->>'count','')!~'^[0-9]+$'
    OR COALESCE(entry.value->>'digest','')!~'^[0-9a-f]{64}$'
    OR jsonb_typeof(entry.value->'fields') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'Command manifest ownership differs'; END IF;
 END LOOP;
 FOR physical,family,binding IN SELECT * FROM (VALUES
   ('dbm_normacceptancetbl','NormAcceptanceTbl','DBM/NormAcceptanceTbl'),
   ('dbm_normsinsleepmodetbl','NormsInSleepModeTbl','DBM/NormsInSleepModeTbl'),
   ('dbm_suggestions','Suggestions','DBM/Suggestions'),
   ('bpr_elephantorders','ElephantOrders','BPR/ElephantOrders')) AS families(p,f,b) LOOP
  EXECUTE format('SELECT count(*) FROM mta_state.%I WHERE vf_run_id=$1 AND vf_image=$2',physical)
   INTO actual USING NEW.run_id,'action/'||NEW.id::text||'/'||family;
  metadata=NEW.state_manifest->family;
  IF (metadata IS NULL AND actual<>0) OR
     (metadata IS NOT NULL AND actual<>(metadata->>'count')::bigint) THEN
   RAISE EXCEPTION 'Command manifest population differs'; END IF;
 END LOOP;
 NEW.state_sealed=true;
 RETURN NEW;
END
'''.replace('jsonb_object_length_placeholder',
            "(SELECT count(*) FROM jsonb_object_keys(NEW.state_manifest))<>1")

COMPLETE_BODY = r'''
BEGIN
 IF NOT EXISTS(SELECT 1 FROM mta.fresh_mta_runcommand WHERE id=NEW.id
    AND state_sealed AND state_manifest<>'{}'::jsonb) THEN
  RAISE EXCEPTION 'Command must seal its typed state before commit'; END IF;
 RETURN NULL;
END
'''

ROWS_BODY = r'''
DECLARE changes text; item record; owner uuid; image text; parent mta.fresh_mta_calculationrun;
 command mta.fresh_mta_runcommand; family text; expected text; derived boolean;
BEGIN
 FOR changes IN SELECT CASE WHEN TG_OP='DELETE' THEN 'old_rows' ELSE 'new_rows' END
   UNION ALL SELECT 'old_rows' WHERE TG_OP='UPDATE' LOOP
  FOR item IN EXECUTE format('SELECT DISTINCT %I AS owner,%s AS image FROM %I ORDER BY 1,2',
      TG_ARGV[0],CASE WHEN TG_TABLE_SCHEMA='mta_state' THEN 'vf_image' ELSE 'NULL::text' END,changes) LOOP
   owner=item.owner; image=item.image;
   SELECT * INTO parent FROM mta.fresh_mta_calculationrun WHERE id=owner FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Typed state owner is absent'; END IF;
   IF parent.status='RUNNING' THEN CONTINUE; END IF;
   IF TG_OP<>'INSERT' OR parent.status<>'SUCCEEDED' OR TG_TABLE_SCHEMA<>'mta_state' THEN
    RAISE EXCEPTION 'Terminal state images are immutable'; END IF;
   family=NULL; expected=NULL;
   CASE TG_TABLE_NAME
ACTION_CASES
   ELSE NULL;
   END CASE;
   IF family IS NOT NULL AND image ~ ('^action/[0-9]+/'||family||'$') THEN
    SELECT * INTO command FROM mta.fresh_mta_runcommand
     WHERE id=split_part(image,'/',2)::bigint AND run_id=owner FOR SHARE;
    IF NOT FOUND OR command.state_sealed OR command.state_manifest<>'{}'::jsonb
      OR parent.kind<>'DAILY_CHAIN'
      OR (family='ElephantOrders' AND command.payload->>'operation' IS DISTINCT FROM 'elephant_due_date')
      OR (family='NormAcceptanceTbl' AND COALESCE(command.payload->>'operation','') NOT IN ('APPLY','SLEEP'))
      OR (family IN ('NormsInSleepModeTbl','Suggestions') AND command.payload->>'operation' IS DISTINCT FROM 'SLEEP')
      OR EXISTS(SELECT 1 FROM mta.fresh_mta_calculationrun WHERE predecessor_id=owner AND status IN ('RUNNING','SUCCEEDED')) THEN
     RAISE EXCEPTION 'Action image requires its live unsealed command'; END IF;
    CONTINUE;
   END IF;
   derived=false;
   CASE TG_TABLE_NAME
DERIVED_CASES
   WHEN 'report_export_row','report_export_cell' THEN
    derived=EXISTS(SELECT 1 FROM jsonb_array_elements(parent.production_manifest->'reports') S
     WHERE S ? 'deferred' AND image IN
       ('reports/'||(S->>'stage')||'/ReportHeader','reports/'||(S->>'stage')||'/ReportRows'));
   ELSE NULL;
   END CASE;
   IF derived AND parent.kind='DAILY_CHAIN' AND parent.production_manifest->>'version'='3'
     AND owner::text=current_setting('fresh.report_generation',true) THEN
    PERFORM 1 FROM mta.fresh_mta_dailyreportgeneration WHERE run_id=owner
     AND status='INCOMPLETE' AND source_digest=parent.production_digest FOR UPDATE;
    IF FOUND THEN CONTINUE; END IF;
   END IF;
   RAISE EXCEPTION 'Terminal insert requires its exact command or report generation';
  END LOOP;
 END LOOP;
 RETURN NULL;
END
'''.replace('ACTION_CASES', '\n'.join(
    "   WHEN '" + table + "' THEN family='" + family + "';"
    for table, (family, _) in ACTION_TABLES.items())).replace('DERIVED_CASES', '\n'.join(
    "   WHEN '" + table + "' THEN derived=image='" + image + "';"
    for table, image in DERIVED_IMAGES.items()))

FUNCTIONS = {'guard_terminal_run': RUN_BODY, 'deny_accepted_truncate': TRUNCATE_BODY,
             'guard_command_seal': COMMAND_BODY, 'require_command_complete': COMPLETE_BODY,
             'guard_accepted_rows': ROWS_BODY}
