            FORWARD += ('CREATE TRIGGER ' + name + ' AFTER ' + op + ' ON ' + schema + '.' + table +
                ' REFERENCING ' + ref + ' FOR EACH STATEMENT EXECUTE FUNCTION mta.guard_accepted_rows(\'' + field + '\');\n')
            TRIGGERS.append((schema, table, name))
